const { IntegrationNotConfiguredError } = require('../lib/errors');
const { USE_MOCKS } = require('../mocks');
const { saveReportFile } = require('../mocks/storage.mock');

/**
 * Writes the report where the spec says and returns its path for Audit.pdfPath.
 * Downloads read the copy in Postgres, because /tmp is not shared between Vercel function calls.
 * @param {string} auditId generated by the server, never user input
 * @param {Buffer} bytes
 * @param {{ reportsDir: string }} options
 */
async function storeReportFile(auditId, bytes, { reportsDir }) {
  if (USE_MOCKS) return saveReportFile(reportsDir, auditId, bytes);
  // Real Cloudflare R2 upload goes here. It needs R2_*.
  throw new IntegrationNotConfiguredError('Cloudflare R2 is not connected', { integration: 'Cloudflare R2' });
}

module.exports = { storeReportFile };
